import { runScript } from '../../sdk/runner';

const deadline = Date.parse('2026-10-21T20:45:48.427Z');
const DONE = new Set(['rat','man','woman','giant rat','goblin','duck','giant spider','imp','spider','tramp','jonny the beard','mugger','barbarian woman','dark wizard']);

function esc(s: string) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

await runScript(async ({ bot, sdk }) => {
  const killed: string[] = [];

  async function fight(name: string | RegExp, ms: number): Promise<boolean> {
    const end = Date.now() + ms;
    while (Date.now() < end && Date.now() < deadline - 30000) {
      const st = sdk.getState();
      if (!st) break;
      if (st.player.hp <= 6) return false;
      const t = sdk.findNearbyNpc(name, { reachable: true });
      if (!t) return true;
      if (!st.player.inCombat) await bot.attack(name).catch(() => {});
      await sdk.waitForTicks(1);
    }
    return false;
  }

  // Head to Varrock (guards lvl 21)
  const target = sdk.findNearbyNpc(/^guard$/i, { reachable: true });
  if (!target) {
    console.log('walking to Varrock...');
    await bot.walkTo(3222, 3418, 8).catch((e) => console.log('walkerr', e?.message));
  }
  let st = sdk.getState();
  console.log('at', st.player.worldX, st.player.worldZ, 'hp', st.player.hp);
  console.log('near', st.nearbyNpcs.slice(0, 16).map((n) => n.name + (n.combatLevel ? '(' + n.combatLevel + ')' : '')).join(', '));

  if (!sdk.findNearbyNpc(/^guard$/i, { reachable: true })) {
    await bot.walkTo(3218, 3432, 6).catch(() => {});
    console.log('near2', sdk.getState().nearbyNpcs.slice(0, 16).map((n) => n.name + (n.combatLevel ? '(' + n.combatLevel + ')' : '')).join(', '));
  }

  const ok = await fight(/^guard$/i, 70000);
  console.log('guard fight result', ok, 'hp', sdk.getState().player.hp);
  if (ok) killed.push('Guard');

  // then opportunistic: any new reachable npc with combat level <= 30
  const end = deadline - 45000;
  while (Date.now() < end) {
    const s = sdk.getState();
    if (!s) break;
    if (s.player.hp <= 6) break;
    const cand = s.nearbyNpcs.find((n) => n.combatLevel && n.combatLevel <= 30 && !DONE.has(n.name.toLowerCase()) && sdk.findNearbyNpc(new RegExp('^' + esc(n.name) + '$', 'i'), { reachable: true }));
    if (!cand) {
      await bot.walkTo(s.player.worldX + 6, s.player.worldZ + 6, 4).catch(() => {});
      await sdk.waitForTicks(2);
      continue;
    }
    console.log('opp target', cand.name, cand.combatLevel);
    const got = await fight(new RegExp('^' + esc(cand.name) + '$', 'i'), 40000);
    if (got) { killed.push(cand.name); DONE.add(cand.name.toLowerCase()); }
  }

  console.log('KILLED_THIS_RUN:', killed.join(', '), 'hp', sdk.getState().player.hp);
}, { timeout: 400_000 });

