import { runScript } from '../../sdk/runner';

const deadline = Date.parse('2026-10-21T20:45:48.427Z');
const DONE = new Set(['rat','man','woman','giant rat','goblin','duck','giant spider','imp','spider','tramp','jonny the beard','mugger','barbarian woman','dark wizard','guard']);

function esc(s: string) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

await runScript(async ({ bot, sdk }) => {
  const killed: string[] = [];

  async function fight(name: string | RegExp, ms: number): Promise<boolean> {
    const end = Date.now() + ms;
    while (Date.now() < end && Date.now() < deadline - 20000) {
      const st = sdk.getState();
      if (!st) break;
      if (st.player.hp <= 6) return false;
      const t = sdk.findNearbyNpc(name, { reachable: true });
      if (!t) return true;
      if (!st.player.inCombat) await bot.attack(name).catch(() => {});
      await sdk.waitForTicks(1);
    }
    return false;
  }

  console.log('walking to Draynor...');
  await bot.walkTo(3102, 3248, 8).catch((e) => console.log('walkerr', e?.message));
  let st = sdk.getState();
  console.log('at', st.player.worldX, st.player.worldZ, 'hp', st.player.hp);
  console.log('near', st.nearbyNpcs.slice(0, 18).map((n) => n.name + (n.combatLevel ? '(' + n.combatLevel + ')' : '')).join(', '));

  // Wizard (lvl 9) first
  if (sdk.findNearbyNpc(/^wizard$/i, { reachable: true })) {
    const ok = await fight(/^wizard$/i, 45000);
    console.log('wizard', ok, 'hp', sdk.getState().player.hp);
    if (ok) { killed.push('Wizard'); DONE.add('wizard'); }
  }

  // opportunistic new names up to lvl 15
  const end = deadline - 30000;
  while (Date.now() < end) {
    const s = sdk.getState();
    if (!s) break;
    if (s.player.hp <= 6) break;
    const cand = s.nearbyNpcs.find((n) => n.combatLevel && n.combatLevel <= 15 && !DONE.has(n.name.toLowerCase()));
    if (!cand) {
      await bot.walkTo(s.player.worldX + 8, s.player.worldZ, 5).catch(() => {});
      await sdk.waitForTicks(2);
      continue;
    }
    console.log('opp', cand.name, cand.combatLevel);
    const got = await fight(new RegExp('^' + esc(cand.name) + '$', 'i'), 35000);
    if (got) { killed.push(cand.name); DONE.add(cand.name.toLowerCase()); }
  }

  console.log('KILLED_THIS_RUN:', killed.join(', '), 'hp', sdk.getState().player.hp);
}, { timeout: 400_000 });
